public class EmbeddingService
{
    private readonly IEmbeddingClient _openAi;
    private readonly IEmbeddingClient _azure;
    private readonly IRedisCache _cache;
    private readonly ILogger _logger;

    public EmbeddingService(
        IConfiguration config,
        IRedisCache cache,
        ILogger logger)
    {
        var provider = config["Embedding:Provider"];
        var model = config["Embedding:Model"];
        _openAi = new OpenAIEmbeddingClient(model, config["OpenAI:ApiKey"]);
        _azure = new Azure.AI.OpenAI.AzureOpenAIEmbeddingClient(
            new Uri(config["Azure:Endpoint"]),
            new AzureKeyCredential(config["Azure:Key"]), model);
        _cache = cache;
        _logger = logger;
    }

    public async Task<float[]> GenerateEmbeddingAsync(
        string text, int? dimensions = null, CancellationToken ct = default)
    {
        // Deduplicate by content hash
        var cacheKey = $"emb:{dimensions}:{Sha256(text)}";
        var cached = await _cache.GetAsync<float[]>(cacheKey, ct);
        if (cached != null) return cached;

        var options = new EmbeddingGenerationOptions
        {
            Dimensions = dimensions, // text-embedding-3-small supports 256–1536
            // For instruction-following: prepend task description
        };

        var response = await _openAi.GenerateEmbeddingAsync(text, options, ct);
        var embedding = response.Value.ToArray();

        await _cache.SetAsync(cacheKey, embedding, TimeSpan.FromHours(24), ct);
        _logger.LogInformation("Generated embedding: {Tokens} tokens, {Dims} dims", response.Value.Count, embedding.Length);
        return embedding;
    }
}

